    }
  ],
  "differences": [
    {
      "point": "Parentage: Britannica says only Jupiter, Wikipedia also cites Hesiod making her daughter of Eris",
      "quote_britannica": "She was daughter of Jupiter, and cast down from heaven at the birth of Hercules.",
      "quote_wikipedia": "Homer calls Ate the daughter of Zeus, while Hesiod has Ate as the daughter of Eris (Strife)."
    },
    {
      "point": "Meaning of the name: Britannica says 'to hurt', Wikipedia gives delusion, recklessness, folly, ruin",
      "quote_britannica": "The name of the goddels comes from stars, men, to hart.",
      "quote_wikipedia": "In Greek mythology, Ate (Ancient Greek: Ἄτη, romanized: Átē, lit. ' Delusion, Recklessness, Folly, Ruin ') is the personification of moral blindness and error."
    },
    {
      "point": "Nature of the figure: Britannica calls her a goddess of mischief, Wikipedia describes her as a personification of moral blindness and error",
      "quote_britannica": "ATE, the goddels of mithief; in the Pagan tho-ology.",
      "quote_wikipedia": "In Greek mythology, Ate (Ancient Greek: Ἄτη, romanized: Átē, lit. ' Delusion, Recklessness, Folly, Ruin ') is the personification of moral blindness and error."
    },
    {
      "point": "Reason for banishment: Britannica ties it to mischief at Hercules' birth, Wikipedia specifies Zeus was blinded to Hera's trickery",
      "quote_britannica": "For Juno ha-ving decided Jupiter, in scaling Enulflets to be born before Hercules, Jupiter expelled his retirement on Ates, as the author of that miichief; and threw her headlong from heaven to earth, featuring the floodal never return children again",
      "quote_wikipedia": "Zeus blamed Ate for clouding his mind causing him not to see Hera's deception. In great anger Zeus grabbed Ate by the hair and flung her from Mount Olympus, and thereby Ate came to inhabit the \"fields of men\"."
    }
  ],
  "claims": [
    {
      "claim": "Ate is the goddess of mischief in Pagan theology",
      "tag": "renamed",
      "quote_britannica": "ATE, the goddels of mithief; in the Pagan tho-ology.",
      "quote_wikipedia": "In Greek mythology, Ate (Ancient Greek: Ἄτη, romanized: Átē, lit. ' Delusion, Recklessness, Folly, Ruin ') is the personification of moral blindness and error."
    },
    {
      "claim": "Ate was the daughter of Jupiter",
      "tag": "enduring",
      "quote_britannica": "She was daughter of Jupiter, and cast down from heaven at the birth of Hercules.",
      "quote_wikipedia": "Homer calls Ate the daughter of Zeus, while Hesiod has Ate as the daughter of Eris (Strife)."
    },
    {
      "claim": "Ate was cast down from heaven at the birth of Hercules",
      "tag": "enduring",
      "quote_britannica": "She was daughter of Jupiter, and cast down from heaven at the birth of Hercules.",
      "quote_wikipedia": "Ate was banished from Olympus by Zeus for blinding him to Hera 's trickery denying Heracles his birthright."
    },
    {
      "claim": "Jupiter expelled Ate because Juno had decided that Eurystheus should be born before Hercules",
      "tag": "enduring",
      "quote_britannica": "For Juno ha-ving decided Jupiter, in scaling Enulflets to be born before Hercules, Jupiter expelled his retirement on Ates, as the author of that miichief; and threw her headlong from heaven to earth, featuring the floodal never return children again",
      "quote_wikipedia": "According to Agamemnon, when Alcmene was about to give birth to Zeus's son Heracles, Zeus, in his great pride, boasted that on that day would be born a man, of Zeus's blood, who would be king of the Argives. But Hera tricked Zeus into swearing an unbreakable oath such that whatever man, of Zeus's blood, born that day would be king. Then Hera delayed the birth of Heracles, and caused Eurystheus, the great-grandson of Zeus, to be born prematurely, and thus Heracles lost the birthright Zeus had intended for him."
    },
    {
      "claim": "Jupiter threw Ate headlong from heaven to earth and she would never return",
      "tag": "enduring",
      "quote_britannica": "Jupiter expelled his retirement on Ates, as the author of that miichief; and threw her headlong from heaven to earth, featuring the floodal never return children again",
      "quote_wikipedia": "So said he, and whirling her in his hand flung her from the starry heaven, and quickly she came to the tilled fields of men."
    },
    {
      "claim": "The name of the goddess comes from a Greek word meaning to hurt",
      "tag": "renamed",
      "quote_britannica": "The name of the goddels comes from stars, men, to hart.",
      "quote_wikipedia": "The meaning of her name, the Greek word atē (ἄτη), is difficult to define. Atē is a verbal noun of the verb aáō (ἀάω). According to The Cambridge Greek Lexicon, aáō means to \"lead astray\", \"befuddle\", \"blind\", or \"delude\", while ἄτη can mean: (1) the state of \"delusion, infatuation (inflicted on a person's mind by a god, esp Zeus)\", (2) \"reckless behavior... recklessness, folly\", and (3) \"ruin, calamity, harm\"."
    },
    {
      "claim": "Her being the daughter of Jupiter means that no evil happens to us but by the permissive providence",
      "tag": "dropped",
      "quote_britannica": "Her being the daughter of Jupiter means, according to mythologiils, has no evil happens to us but by the permitief providence, and her healthment to earth denotes the terrible effects of divine jul-tice among men.",
      "quote_wikipedia": null
    },
